var items = $input.all();
var src = items.length ? items[0].json : {};
var body = (src.body && typeof src.body === 'object') ? src.body : {};
var query = (src.query && typeof src.query === 'object') ? src.query : {};
function pick(name, fallback){
  if (body[name] !== undefined && body[name] !== null && body[name] !== '') return body[name];
  if (query[name] !== undefined && query[name] !== null && query[name] !== '') return query[name];
  if (src[name] !== undefined && src[name] !== null && src[name] !== '') return src[name];
  return fallback;
}
var keyRe = new RegExp('^[a-z0-9_-]{1,50}$');
var key = String(pick('sequence_key', 'invoice')).trim().toLowerCase();
if (!keyRe.test(key)) key = 'invoice';
var prefixRe = new RegExp('^[A-Za-z0-9_-]{0,12}$');
var prefix = String(pick('prefix', '')).trim();
if (!prefixRe.test(prefix)) prefix = '';
var pad = parseInt(pick('pad', 6), 10);
if (!isFinite(pad) || pad < 1) pad = 6;
if (pad > 12) pad = 12;
return [{ json: { sequence_key: key, prefix: prefix, pad: pad, prefix_requested: prefix.length > 0 } }];

var req = $('Read Sequence Request').first().json;
var items = $input.all();
var row = (items.length && items[0].json && typeof items[0].json === 'object') ? items[0].json : {};
var stored = Number(row.current_value);
if (!isFinite(stored) || stored < 0) stored = 0;
stored = Math.floor(stored);
var next = stored + 1;
var prefix = req.prefix_requested ? req.prefix : (typeof row.prefix === 'string' ? row.prefix : '');
var digits = String(next);
while (digits.length < req.pad) { digits = '0' + digits; }
return [{ json: {
  sequence_key: req.sequence_key,
  current_value: next,
  previous_value: stored,
  prefix: prefix,
  formatted_number: prefix + digits,
  updated_at: new Date().toISOString()
} }];
